(243, '292a7429-f28d-4243-adf1-90da4168954d', '', '', '', 10, 'Tyranastros', 'Blood DK Tank Leveling Build', '', '### OVERVIEW\nA Blood DK  tank leveling build that centers on increasing self healing from Death Strike.\n\nBasic Rotation:\nApply Diseases (Icy Touch + Plague Strike)\nMaintain with Pestilence, follow-up with Blood Boil for Blade Barrier effect (5% dmg taken reduction)\nDeath Strike\nThunder Clap\n\nFor AoE:\nSummon Void Zone + Death and Decay\nApply Diseases, spread & maintain with Pestilence\nDeath Strike\nThunder Clap', 'ability_felarakkoa_feldetonation_red', 0, 1786862531, 1787244132, 1, 2, 0, 0, 1),
(244, '938b0e51-f7e3-49bf-a323-b36a6330095c', '', '', '', 10, 'Banboo', '最强单奶大圣光', '', '### OVERVIEW\n新人必备，简单无脑，堆智力暴击就够了', 'ability_priest_spiritoftheredeemer', 0, 1786868558, 1786868558, 2, 8, 4, 0, 4),
