INSERT INTO `coa_build_creator` (`entry`, `id`, `leveling_id`, `pve_id`, `pvp_id`, `class`, `author`, `name`, `subtext`, `description`, `icon`, `upvotes`, `created`, `updated`, `category`, `roles`, `primary_stat`, `flags`, `difficulty`) VALUES
(251, '81ca2236-e611-4e99-8ea7-08a05a9e916f', '', '', '', 10, 'Moghadina', 'Reset Spec Reset Talents Empty -- make it simple', '', '### OVERVIEW\nsadly not 100% empty, but using this should help make it easier to reset talents and abilities without the pathing issue.\n\nenable "auto learn spells" and activate this build. then unlearn an ability or talent and deactivate again. this should leave you only with few spells and talents, which are all easy to remove for a mere 14 Scrolls of Unlearning.\n\nremember: you can get Scrolls of Unlearning from the Guardian of Time (Bloodelf next to the callboard) for 250 Runes, if you have <10 left.\nunlearning will tell you how much runes this will cost, but as long as you have scrolls, they will be used instead (1 Scroll = 250 Runes. if it says "1250 Runes to unlearn" this will be 5 Scrolls)', 'ability_evoker_reversion', 4, 1786966739, 1786967695, 2, 8, 0, 0, 0),
(252, 'e3476bbd-ebf9-4248-ae9f-7f38b6de1b55', '', '', '', 10, 'Snapcaster', 'BIG DIK IMP AND FRIENDS - Bloodlust Totems', '', '### OVERVIEW\nnormal imp build but with bloodlust and fire ele totem', 'Spell_Fire_Elemental_Totem', 0, 1786966869, 1786966878, 2, 8, 3, 0, 0),
