INSERT INTO `coa_build_creator` (`entry`, `id`, `leveling_id`, `pve_id`, `pvp_id`, `class`, `author`, `name`, `subtext`, `description`, `icon`, `upvotes`, `created`, `updated`, `category`, `roles`, `primary_stat`, `flags`, `difficulty`) VALUES
(326, 'da131f5a-e142-416f-b7d7-3e06f409b8f0', '', '', '', 10, 'Illicide', 'Shadow Artillery DK', '', '### OVERVIEW\nThis build is designed for MS but is also pretty viable in questing and solo play, enjoy and make sure to check mystic enchants section! (has a very important ability you should get immdiately.) \n\n(PS: FOR TANKING I SUGGEST FROST, IF UR OFF TANKING USE UNHOLY!!)\n\nThis build works best with heirlooms!\n\nAfter Lvl 34 fill with whatever you would like feel free to disable the build and use it as a guideline to make it something your own!\n\n### PROS_AND_CONS\n|cff1aff1a+PROS:|r\n|cff1aff1a+Great Threat Generation|r\n+Great DPS Output\n+Fun Pets and Army of the Dead\n+Incredibly Tanky and Sustainable\n\n\n-CONS\n-Slow Movement\n-Better in MS than leveling by quests\n-Boring until required mystic enchants are acquired (although its easy to get them)\n\n### ITEMIZATION\nN/A\n\n### ROTATION\nMostly whatever you make it\n\nBone Toss ME: Start with bone toss to grab enemies from a far, bring them in, Death & Decay, then Blood Boil and Pestilence after, fill with Shadow Siphon and Blood Boil.\n\nNo Bone Toss: Taunt an enemy if in Frost Presence, Blood Boil to start, then Death & Decay ontop yourself, Pestilence after, fill with Shadow Siphon and Blood Boil.\n\nFor Bosses: Save your Shadow Artillery and Army of the Dead until you\'re at bosses and then drop Army before you pull, once pulling use both charges of Shadow Artillery and then fill with Shadow Siphon.\n\n### CONSUMABLES\nN/A \nEXP AURA HELPS\nEXP POTS ARE HUGE USE UR LP FOR THEM!\n\n### MACROS\nN/A\n\n### WEAKAURAS\nN/A\n\n### NOTES\nHave fun! thanks for using my build and make sure to upvote!', 'ability_argus_deathfog', 2, 1787617781, 1787618616, 1, 2, 0, 0, 0),
(327, '9b0beafe-2abc-4cc7-bc2f-d3330fe5b6eb', '', '', '', 10, 'Saera', 'Shadow Artillery Knight', '', '### OVERVIEW\nThis is a relatively simple build to tank MS Lvling Groups that is effective starting at lv16 with Shadow Artillery and stronger at lv34 with Army of the Dead.\n\nUtilize Mage Frost/Ice Armor to slow enemies, Warlock Demon Skin/Armor for Bonus Healing Received, and Hunter Aspect of the Hawk for Ranged AP.\n\nPriest\'s Devouring Plague counts as a healing DoT that also counts as a DK disease modifier.\n\nIn MS, Shadow Artillery has no range minimum, in Open World, you need to kite to get the minimum range.\n\n### PROS_AND_CONS\n|cff1aff1a+Easy Tanking and High DPS|r\n\n-What Cons?\n\n### ITEMIZATION\nMail or Plate.\n\nAdd some Defense items, but mostly just Strength & Stamina.\n\n### ROTATION\nSpam [Endless Manastorm Potion] for HP & MP\n\nGenerally:\nIcy Touch > Plague Strike > Pestilence > Shadow Artillery > Shadowy Bloodstrike > Shadow Siphon > Pestilence (to refresh diseases)\n\nAugment with:\nBone Shield > Summon Void Zone > Death and Decay> other CDs\n\nIf boss, open with Army of the Dead\n\n### CONSUMABLES\nWhatever works for you.\n\n[Endless Manastorm Potion]\n\n### MACROS\nOnly if you want to RP.\n\n### WEAKAURAS\nFor weak people.\n\n### NOTES\nIf you mess this up, that\'s on you.', 'ability_bossdarkvindicator_auraofmalice', 3, 1787622181, 1787622690, 1, 2, 0, 0, 2),
(328, '41bdd41d-a0e1-4717-bbfe-6e924757aee6', '', '', '', 10, 'Belleirus', 'aswrwefqgq', '', '### OVERVIEW\netrhj4jw', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1787624717, 1787624717, 2, 8, 0, 0, 3),
(329, 'e1284fe2-4263-41d3-9f62-f5cf450b4cc4', '', '', '', 10, 'Medeas', 'Attack Speed', '', '### OVERVIEW\nRogue - Shaman build, mostly\n\n### PROS_AND_CONS\n|cff1aff1a+Sustean, always a button to press, have a pet -On test, have a pet\n\n### ITEMIZATION\nNeed a quick off hand axe or sword\n\n### ROTATION\nDevastate>Mutilate>Mutilate>Finishing Move', 'ability_demonhunter_bladedance', 0, 1787626900, 1787626900, 1, 8, 1, 0, 0),
(330, '9143501c-f8dc-477b-9555-9e083a9063ae', '', '', '', 10, 'Gutfor', 'Lava sweep + Sunder', '', '### OVERVIEW\nWIP\n\nYou want to wait until you have 4 stacks to use sunder. It will hit 25-30k to each target if it crits and is uncapped AOE.\n\n18k on dummies sustained over 10 minutes\n\n5.5k ST using one button macro not optimized for ST but will do ok on bosses\n\nThis is meant for mythic dungeons - better results manually casting. Super fun spec to play similar to my divinestorm build\n\n{HT}showtooltip\n/castsequence reset=10 lava sweep, bloodthirst, incinerate, whirling flames,lava sweep, bloodthirst, incinerate, stormstrike\n/cast! flamebound cleave\n/startattack\n\nRotation:\n\nLava Sweep -> Flame Surge (Maelstrom) -> Bloodthirst -> Stormstrike -> Whirlwind\n\n### MACROS\n{HT}showtooltip\n/castsequence reset=10 lava sweep, bloodthirst, incinerate, whirling flames,lava sweep, bloodthirst, incinerate, stormstrike\n/cast! flamebound cleave\n/startattack', 'ability_foundryraid_blastwave', 0, 1787634868, 1787659431, 2, 8, 0, 0, 0),
(331, 'a99a1d97-8f8b-4c3c-a0a4-204b10f059ab', '', '', '', 10, 'Gutfor', ',', '', '### OVERVIEW\n,\n\n### PROS_AND_CONS\n,', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1787663044, 1787663044, 2, 8, 0, 0, 0),
(332, '3b8f7574-71f9-4173-ba01-8a4dfa5f9399', '', '', '', 10, 'Velenar', 'Arcane Hunter (Missiles and Arrows Pew Pew)', '', '### OVERVIEW\nInspired from Starcaller (Sentinel), but instead or Druidic Lunar Magic, you\'re doing arcane magic.\nWeave arcane power onto your ranged attacks, using Arcane missile and Arcane blast alongside Arcane arrows and bullets\n\nNo exact "rotation", you only looking to trigger missile barrage to active\nCentered around Arcane missiles\nSpam missile each time the missile barrage is actice\n\nBit onto glass cannon side, so Kite enemies using concussive shot and slow\n\nDuality based as we combine magic and physical attacks\n\n### PROS_AND_CONS\n|cff1aff1a+Strong Fire power|r\n- Lower survivability\n\n### ROTATION\nHunter mark first as usual\n\nSIMPLE\n\nOnly blast Arcane Missile when Missile Barrage is ON (Much Faster Missiles, No Mana cost)\nTrigger Missile barrage by doing spells like Arcane Blast, Arcane Arrow, Arcane Buller, etc\nTime bomb for extra damage (i genuinely don\'t know what mystic enchant  to put here lol)\nNo exact rotation\n\nfor AOE, cast rain arrow then channel volley.\n\nslow and kite as needed with concussive shot, slow, and blink\n\nUse the macro to gain all the buff skills immediately\nreadiness to reset some of the buffs\n\nEvocation when OOM, but rarely OOM on higher level\n\nAspect of hawk or dragonhawk, Arcane brilliance/intellect, Amplify magic should be always used\n\n### MACROS\n/cast Rapid Fire\n/cast Warcry\n/cast Presence of Mind\n/cast Brilliance Aura\n/cast Arcane Power\n\n### NOTES\nI only make this one i hit 30-40ish\nCan\'t test for lower level', 'spell_azerite_essence03', 0, 1787683223, 1787683223, 2, 8, 1, 0, 0),
(333, 'aea7af6a-d7d9-42aa-b7ac-c05862bc531b', '', '', '', 10, 'Gandonio', 'Frozen Chaos aoe monster', '', '### PROS_AND_CONS\ncrazy aoe\nvery underwhelming and clunky st\n\n### ITEMIZATION\ncrit\n\n### ROTATION\nAoE: \nimmolate -> hydricle -> glacial spike -> conflagrate -> x5 chaos bolt repeat\nST prio:\nspirit tap (chaos bolt) > empowering frostbolt > fire and brimstone \nbuild up frozen chaos stacks, conflagrate and cds right before chaos bolts spam, make sure empowering frostbolt is up\nwith bloodlust or haste cds spam frostfire bolt for fc stacks (backdraft)\nbeam of hatred helps with fof a little bit but the damage should be 5-10 times more before it can be a good button', 'spell_animamaldraxxus_buff', 0, 1787713157, 1787713157, 2, 8, 3, 0, 0),
(334, '80a0d9a4-a555-4d33-92eb-0c8784e4a951', '', '', '', 10, 'Opto', '7K DK', '', '### OVERVIEW\ntest dk', 'ability_accretion', 0, 1787717270, 1787947989, 2, 8, 0, 0, 0),
(335, 'd20ca640-f3ca-43e8-bf3f-ee7d2a63438d', '', '', '', 10, 'Komodo', 'Arcane/Divine Melee', '', '### OVERVIEW\nArcane/Divine Mage+Pally melee build', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1787718244, 1787718244, 2, 8, 3, 0, 0),
(336, '23880f65-6bc2-4dbb-a37e-de7e2fe2d6dc', '', '', '', 10, 'Greafr', 'GREAFS MAX ZUGGATRY', '', '### OVERVIEW\nMAXIMUM ZUGGATRY||\nTHIS IS A DUALITY BUILD STACK AGIL AND INT WITH HASTE ,HIT ,CRIT\nWFITEMS WORK WELL WITH THIS BUILD', 'ability_mount_whitedirewolf', 1, 1787752355, 1787752355, 3, 8, 0, 0, 2),
(337, '655f9191-e8aa-436c-a708-0ef520f2eff6', '', '', '', 10, 'Sarahphina', 'Fel Dk', '', '### OVERVIEW\nThis build is basically fel, Blood dk, with blood thirst. keep high plate. and cleave through groups of enemies with fel cleaves and burst down bosses with chaos bolt\n\n### PROS_AND_CONS\nLooks to be good Physical and magical damage\n\n### ITEMIZATION\nPaladin spell power plate and strength gear\n\n### ROTATION\n-\n\n### CONSUMABLES\n-\n\n### MACROS\n-\n\n### WEAKAURAS\n-\n\n### NOTES\nNo notes', 'ability_bossfellord_felspike', 0, 1787772207, 1787772207, 2, 8, 0, 0, 2),
(338, '5bf15590-855d-4ed7-85ad-c840856cfd5f', '', '', '', 10, 'Verigren', 'Tommy', '', '### OVERVIEW\n***In progress build for a Grove Ranger-style healer***\n\nBest Ranger of all time... the Green Ranger, Tommy.', 'ability_demonhunter_eyeofleotheras', 0, 1787789683, 1787789683, 1, 4, 4, 0, 0),
(339, '7fe87e95-f84f-4593-bc0b-72ffa75102dc', '', '', '', 10, 'Holygnome', 'THE LORD OF ALL LIGHTNING!!', '', '### OVERVIEW\nBUILD STACKS OF BOOMING THUNDER WITH SPAM CHAIN LIGHNING AND LOCALIZED STORM\n\n### ITEMIZATION\nHIT>INT>SPIRIT>CRIT>', 'spell_animaardenweald_debuff', 0, 1787797746, 1787797746, 2, 8, 3, 0, 1),
(340, 'b579d1ea-1d5c-4757-bb2c-62ed82282457', '', '', '', 10, 'Gutfor', 'M+ Tanking', '', '### OVERVIEW\nUpdated for QOL\n\nCTC w/ holy shield\n11.5k hp self buffed\nJuggernaut talent is OP', 'ability_blackhand_slagbombs', 0, 1787818891, 1787818975, 2, 8, 0, 0, 0),
(341, '2de5263b-c570-4245-8798-89673dd32391', '', '', '', 10, 'Asured', 'Weeb ahh Naruto ahh build', '', '### OVERVIEW\nSimple toss build\n\nwaaw\n\n### PROS_AND_CONS\nPros : High aoe dmg, Easy to use \n\nCons: only abt 6-9k dps  on single target\n\n### ITEMIZATION\nAgility/Atk power > Crit > everything else\n\n### ROTATION\nShuriken Toss,Deadly throw,Shuriken Toss,Shuriken Toss (Thats the whole rotation) (on bosses pop cold blood)\n\n### CONSUMABLES\nEnchant both your weapons with ninja\'s focus\n\n### MACROS\n{HT}showtooltip\n/castsequence reset=2 Shuriken Toss,Deadly throw,Shuriken Toss,Shuriken Toss', 'ability_psychicassault', 1, 1787866410, 1787866767, 2, 8, 1, 0, 0),
(342, 'd8517c9e-2679-4b16-8da8-60bd5ba2dffb', '', '', '', 10, 'Gandonio', 'VL crit', '', '### ROTATION\nlol', 'ability_priest_halo_shadow', 0, 1787869981, 1787869981, 2, 4, 3, 0, 0),
(343, '866ceb47-d5a7-4d55-ab61-010fafd9dbf1', '', '', '', 10, 'Idum', 'Rottentreats Necromancer', '', '### OVERVIEW\nCreate this build for a player that did prefere the caster version of Idum\'s Crypt Ranger.\ni can\'t promise it works correctly because i haven\'t tested this one.', 'ability_deathknight_decomposingaura', 0, 1787877214, 1787877214, 1, 8, 3, 0, 0),
(344, '1867689b-a510-4e5c-b756-9519f58450ea', '', '', '', 10, 'Valrak', 'Prot Pali Spec VI', '', '### OVERVIEW\nFor when the game messes up specs', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1787880557, 1787880557, 2, 2, 0, 0, 0),
(345, '078e8d9e-2bbc-45a6-9809-d07807f1b586', '', '', '', 10, 'Belleirus', 'aas', '', '### OVERVIEW\nasas', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1787882634, 1787882634, 2, 8, 3, 0, 0),
(346, '26140c92-2350-4d12-bc8c-9678234c7e86', '', '', '', 10, 'Opto', 'best heal spec', '', '### OVERVIEW\nyep', 'ability_bossdarkvindicator_auraofoppression', 0, 1787883573, 1787883573, 2, 4, 4, 0, 0),
(347, '941738a7-fa37-4b15-98a3-b12df48c7812', '', '', '', 10, 'Opto', 'GROVE RANGER TANK', '', '### OVERVIEW\nTANKED UPTO M+15', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1787883667, 1787883667, 2, 2, 4, 0, 0),
(348, 'eaff3d5c-cfe0-451b-bf52-04d91f087b2e', '', '', '', 10, 'Opto', 'BLEEDBOI 8K', '', '### ROTATION\n/castsequence reset=6 razzashi talon,razzashi talon,mongoose bite,disembowel,execute', 'ability_accretion', 0, 1787884417, 1787884417, 2, 8, 0, 0, 0),
(349, '31c9a8e0-a7b7-43bf-8e10-b3b86e691ff2', '', '', '', 10, 'Zerathul', 'Hellcaller', '', '### PROS_AND_CONS\ngreat output if you can keep up the mana\n\n### ROTATION\nunder construction', 'ability_evoker_firestorm', 0, 1787889718, 1787889718, 2, 8, 3, 0, 1),
(350, '9b4df40a-90ac-4d8c-beb2-5c0f57a94197', '', '', '', 10, 'Belleirus', 'aaaaaaaaaaaaaaaaaaaa', '', '### OVERVIEW\naaaaaaaaaaaaa', 'Interface\\Icons\\INV_Misc_QuestionMark', 0, 1787891355, 1787891355, 2, 8, 1, 0, 0);
